1: import Anthropic from "@anthropic-ai/sdk";
2: import readline from "node:readline/promises";
3: import { stdin as input, stdout as output } from "node:process";
4: 
5: import { runAgent } from "./agent/loop";
6: import { loadSession } from "./agent/load";
7: 
8: async function main() {
9:   const rl = readline.createInterface({ input, output });
10: 
11:   const messages: Anthropic.MessageParam[] = [];
12: 
13:   console.log('Coding Agent started. Type "exit" to quit.\n');
14: 
15:   try {
16:     while (true) {
17:       const userInput = await rl.question("> ");
18: 
19:       const prompt = userInput.trim();
20: 
21:       // Exit
22:       if (prompt.toLowerCase() === "exit") {
23:         break;
24:       }
25: 
26:       // Ignore empty input
27:       if (!prompt) {
28:         continue;
29:       }
30: 
31:       // Commands
32:       if (prompt === "/resume") {
33:         const loaded = loadSession();
34: 
35:         if (loaded.length === 0) {
36:           console.log("No previous session found.");
37:         } else {
38:           messages.push(...loaded);
39:           console.log(
40:             `Loaded ${loaded.length} messages from previous session.`,
41:           );
42:         }
43: 
44:         continue;
45:       }
46: 
47:       if (prompt === "/new") {
48:         messages.length = 0;
49:         console.log("Started new session.");
50:         continue;
51:       }
52: 
53:       // Normal user message
54:       messages.push({
55:         role: "user",
56:         content: prompt,
57:       });
58: 
59:       try {
60:         await runAgent(messages);
61:       } catch (error) {
62:         console.error("Agent error:", error);
63:       }
64:     }
65:   } finally {
66:     rl.close();
67:   }
68: }
69: 
70: main().catch(console.error);

1: import Anthropic from "@anthropic-ai/sdk";
2: import client from "../llm/openrouter";
3: import { tools, getTool } from "../tools/registry";
4: import { toJsonSchema } from "../utils/schema";
5: import { AgentState, MAX_ITERATIONS, MAX_TOOL_CALLS } from "./state";
6: 
7: import readline from "node:readline/promises";
8: import { stdin as input, stdout as output } from "node:process";
9: import { truncateResult } from "../context/truncateResult";
10: import { compressMessages } from "../context/compressMessages";
11: import { executeBatches, partitionIntoBatches, ToolCall } from "../utils/utils";
12: import { saveMessage } from "./save";
13: 
14: const SYSTEM_PROMPT = `
15: You are a coding agent that helps users understand and modify codebases.
16: 
17: Tool selection rules:
18: - If the user asks where a specific symbol, function, class, variable, or text appears, use search_files first.
19: - If you need to understand the project structure, use list_directory.
20: - If you know the exact file you need to inspect, use read_file.
21: - Don't read files unnecessarily.
22: - Don't explore files when search_files can answer the question.
23: - Use the minimum number of tool calls necessary.
24: 
25: Verification rules:
26: - After modifying code, determine whether verification is useful.
27: - When verification is appropriate, use the verify tool.
28: - Choose a verification command based on the project and the changes made.
29: - Do not assume a specific programming language, framework, package manager, or test runner.
30: - Inspect project configuration when necessary to determine the appropriate verification command.
31: - Reading a modified file or viewing a diff does not count as verification.
32: - A verification succeeds only when the verification command exits with code 0.
33: - If verification fails, inspect the error, fix the problem, and verify again.
34: - Do not claim that a change was verified unless the verify tool actually succeeded.
35: 
36: Task completion rules:
37: - Once the user's request is completed, stop using tools and provide the final answer.
38: - Do not perform additional investigation after the task is complete.
39: - Do not repeat a tool call with the same arguments unless the previous call failed.
40: - Do not investigate Git history or staged changes unless the user explicitly asks about Git.
41: `;
42: async function askForApproval(): Promise<boolean> {
43:   const rl = readline.createInterface({
44:     input,
45:     output,
46:   });
47: 
48:   try {
49:     const answer = await rl.question("Allow this action? (y/n): ");
50:     return answer.trim().toLowerCase() === "y";
51:   } finally {
52:     rl.close();
53:   }
54: }
55: 
56: export async function runAgent(messages: Anthropic.MessageParam[]) {
57:   const state: AgentState = {
58:     iteration: 0,
59:     toolCalls: 0,
60:     completed: false,
61:   };
62: 
63:   while (
64:     state.iteration < MAX_ITERATIONS &&
65:     state.toolCalls < MAX_TOOL_CALLS &&
66:     !state.completed
67:   ) {
68:     state.iteration++;
69: 
70:     const compressed = await compressMessages(messages);
71: 
72:     // console.log(
73:     //   `\n--- Agent iteration ${state.iteration}/${MAX_ITERATIONS} ---`,
74:     // );
75: 
76:     const stream = client.messages.stream({
77:       model: process.env.PRIMARY_MODEL || "qwen/qwen3-coder",
78:       max_tokens: 2000,
79:       system: SYSTEM_PROMPT,
80: 
81:       tools: tools.map((tool) => ({
82:         name: tool.name,
83:         description: tool.description,
84:         input_schema: toJsonSchema(tool.inputSchema),
85:       })),
86: 
87:       messages: compressed,
88:     });
89: 
90:     stream.on("text", (text) => {
91:       process.stdout.write(text);
92:     });
93: 
94:     const response = await stream.finalMessage();
95:     console.log("\n");
96:     messages.push({
97:       role: "assistant",
98:       content: response.content,
99:     });
100:     saveMessage({ role: "assistant", content: response.content });
101: 
102:     const toolUseBlocks = response.content.filter(
103:       (block): block is Anthropic.ToolUseBlock => block.type === "tool_use",
104:     );
105: 
106:     if (toolUseBlocks.length === 0) {
107:       const textBlocks = response.content.filter(
108:         (block): block is Anthropic.TextBlock => block.type === "text",
109:       );
110: 
111:       return textBlocks.map((b) => b.text).join("\n");
112:     }
113: 
114:     const toolResults: Anthropic.ToolResultBlockParam[] = [];
115: 
116:     const executableToolCalls: ToolCall[] = [];
117: 
118:     for (const block of toolUseBlocks) {
119:       if (state.toolCalls >= MAX_TOOL_CALLS) {
120:         toolResults.push({
121:           type: "tool_result",
122:           tool_use_id: block.id,
123:           content:
124:             "Tool call limit reached. Stop using tools and provide the best final answer.",
125:           is_error: true,
126:         });
127: 
128:         continue;
129:       }
130: 
131:       const tool = getTool(block.name);
132: 
133:       if (!tool) {
134:         toolResults.push({
135:           type: "tool_result",
136:           tool_use_id: block.id,
137:           content: `Unknown tool: ${block.name}`,
138:           is_error: true,
139:         });
140: 
141:         continue;
142:       }
143: 
144:       state.toolCalls++;
145:       state.lastTool = tool.name;
146: 
147:       const requiresApproval = [
148:         "edit_file",
149:         "write_file",
150:         "run_command",
151:         "web_search",
152:       ].includes(tool.name);
153: 
154:       if (requiresApproval) {
155:         if (tool.name === "run_command") {
156:           console.log("\n⚠️ Agent wants to run:");
157:           console.log(`$ ${block.input.command}`);
158:         } else {
159:           console.log("\n⚠️ Agent wants to modify:");
160:           console.log(block.input);
161:         }
162: 
163:         const approved = await askForApproval();
164: 
165:         if (!approved) {
166:           toolResults.push({
167:             type: "tool_result",
168:             tool_use_id: block.id,
169:             content:
170:               "The user denied this action. Do not attempt another command or modification.",
171:             is_error: true,
172:           });
173: 
174:           continue;
175:         }
176:       }
177: 
178:       executableToolCalls.push({
179:         block,
180:         tool,
181:       });
182:     }
183: 
184:     const batches = partitionIntoBatches(executableToolCalls);
185: 
186:     const executedResults = await executeBatches(batches);
187: 
188:     toolResults.push(...executedResults);
189: 
190:     messages.push({
191:       role: "user",
192:       content: toolResults,
193:     });
194:     saveMessage({ role: "user", content: toolResults });
195:   }
196: 
197:   return `Agent stopped because it reached a safety limit. Iterations: ${state.iteration}/${MAX_ITERATIONS}, tool calls: ${state.toolCalls}/${MAX_TOOL_CALLS}.`;
198: }
