1: import fs from "fs";
2: import path from "path";
3: import { z } from "zod";
4: import { Tool } from "./types";
5: 
6: const inputSchema = z.object({
7:   pattern: z.string().describe("Regex pattern to search for"),
8:   directory: z
9:     .string()
10:     .optional()
11:     .describe("Directory to search. Defaults to current directory."),
12: });
13: 
14: export const searchFilesTool: Tool = {
15:   name: "search_files",
16: 
17:   description:
18:     "Search for a regex pattern in files recursively. Returns matching lines with file paths and line numbers.",
19: 
20:   inputSchema,
21: 
22:   async call(input) {
23:     const { pattern, directory } = inputSchema.parse(input);
24: 
25:     const dir = directory || ".";
26:     const regex = new RegExp(pattern);
27:     const results: string[] = [];
28: 
29:     function search(currentDir: string) {
30:       for (const entry of fs.readdirSync(currentDir, {
31:         withFileTypes: true,
32:       })) {
33:         // Skip hidden files and node_modules
34:         if (entry.name.startsWith(".") || entry.name === "node_modules") {
35:           continue;
36:         }
37: 
38:         const fullPath = path.join(currentDir, entry.name);
39: 
40:         if (entry.isDirectory()) {
41:           search(fullPath);
42:         } else {
43:           try {
44:             const lines = fs.readFileSync(fullPath, "utf-8").split("\n");
45: 
46:             lines.forEach((line, index) => {
47:               if (regex.test(line)) {
48:                 results.push(`${fullPath}:${index + 1}: ${line.trim()}`);
49:               }
50:             });
51:           } catch {
52:             // Ignore unreadable/binary files
53:           }
54:         }
55:       }
56:     }
57: 
58:     search(dir);
59: 
60:     return results.slice(0, 50).join("\n") || "No matches found.";
61:   },
62: };
